W1-AFTER-minus-f.source:
pub fn f() -> u32 {
    let ignored = 1;
    line!()
}
const AFTER: u32 = line!();
#[test]
fn t() { assert_eq!(AFTER - f(), 2); }

W1-hidden-track-caller.source:
pub fn f() -> u32 {
    let ignored = 1;
    location()
}
const AFTER: u32 = line!();
#[track_caller]
fn location() -> u32 { std::panic::Location::caller().line() }
#[test]
fn t() { assert_eq!(AFTER - f(), 2); }

unwrap-value-kill.source:
fn f() -> u32 { Some(1).unwrap() }
#[test]
fn t() { assert_eq!(f(), 1); }

unwrap-panic-kill.source:
fn f() -> u32 { Some(1).unwrap() }
#[test]
fn t() { assert_eq!(f(), 1); }

local-safe-macro-kill.source:
macro_rules! lit { () => { 1 }; }
fn f() -> u32 { lit!() + 1 }
#[test]
fn t() { assert_eq!(f(), 2); }

payload-location-confirmation.source:
fn f() -> bool { true }
#[test]
fn t() { assert!(f(), "observed src/lib.rs:12:3"); }

should-panic-location-confirmation.source:
fn f() -> bool { true }
#[test]
#[should_panic(expected="src/lib.rs:")]
fn t() { if f() { panic!("src/lib.rs:"); } else { panic!("wrong"); } }

